/*
 * dotclaude catalog site. Fetches data.json (generated by `pnpm gen`), keeps
 * all view state in the URL hash so any filtered view or open item is a
 * shareable link, and renders with plain DOM APIs. No build step, no deps.
 *
 * Hash grammar:  #/[path][?query]
 *   path   ""              the item list
 *          "plugins"       the plugin bundles
 *          "install"       install instructions and type explainer
 *          "<type>/<name>" an item, opened over the list
 *   query  q, type, category, plugin — the list filters
 */

const DATA_URL = "data.json";

const state = {
  data: null,
  q: "",
  type: "",
  category: "",
  plugin: "",
  view: "items",
  item: null,
};

const $ = (id) => document.getElementById(id);

const els = {
  counts: $("counts"),
  search: $("search"),
  filterType: $("filter-type"),
  filterCategory: $("filter-category"),
  filterPlugin: $("filter-plugin"),
  clear: $("clear"),
  summary: $("summary"),
  rows: $("rows"),
  empty: $("empty"),
  viewItems: $("view-items"),
  viewPlugins: $("view-plugins"),
  viewInstall: $("view-install"),
  pluginList: $("plugin-list"),
  detail: $("detail"),
  detailInner: $("detail-inner"),
  backdrop: $("detail-backdrop"),
  loadError: $("load-error"),
};

/* URL state ---------------------------------------------------------------- */

function readHash() {
  const raw = location.hash.replace(/^#\/?/, "");
  const [path, query = ""] = raw.split("?");
  const params = new URLSearchParams(query);
  state.q = params.get("q") ?? "";
  state.type = params.get("type") ?? "";
  state.category = params.get("category") ?? "";
  state.plugin = params.get("plugin") ?? "";
  state.item = null;
  if (path === "plugins" || path === "install") {
    state.view = path;
  } else {
    state.view = "items";
    if (path.includes("/")) state.item = path;
  }
}

function buildHash(overrides = {}) {
  const next = { ...state, ...overrides };
  const params = new URLSearchParams();
  if (next.q) params.set("q", next.q);
  if (next.type) params.set("type", next.type);
  if (next.category) params.set("category", next.category);
  if (next.plugin) params.set("plugin", next.plugin);
  const query = params.toString();
  let path = "";
  if (next.view === "plugins" || next.view === "install") path = next.view;
  else if (next.item) path = next.item;
  return `#/${path}${query ? `?${query}` : ""}`;
}

function navigate(overrides) {
  const hash = buildHash(overrides);
  if (hash === location.hash) return;
  location.hash = hash;
}

/* Filtering ------------------------------------------------------------------ */

function normalize(s) {
  return s.toLowerCase();
}

function matchesQuery(item, terms) {
  if (terms.length === 0) return true;
  const hay = normalize(`${item.name} ${item.title} ${item.description} ${item.category}`);
  return terms.every((term) => hay.includes(term));
}

function applyFilters(items, { ignore } = {}) {
  const terms = normalize(state.q).split(/\s+/).filter(Boolean);
  return items.filter(
    (item) =>
      matchesQuery(item, terms) &&
      (ignore === "type" || !state.type || item.type === state.type) &&
      (ignore === "category" || !state.category || item.category === state.category) &&
      (ignore === "plugin" || !state.plugin || item.plugins.includes(state.plugin)),
  );
}

/* Rendering helpers ------------------------------------------------------------ */

function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (value === undefined || value === null || value === false) continue;
    if (key === "text") node.textContent = value;
    else if (key === "class") node.className = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children) {
    if (child == null) continue;
    node.append(child);
  }
  return node;
}

function dot(type) {
  return el("span", { class: "dot", "data-type": type, "aria-hidden": "true" });
}

/** Wrap each query term in <mark>, working on text so nothing is injected. */
function highlight(text, terms) {
  if (terms.length === 0) return [text];
  const pattern = new RegExp(`(${terms.map(escapeRegExp).join("|")})`, "ig");
  return text.split(pattern).map((part, i) => (i % 2 === 1 ? el("mark", { text: part }) : part));
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function commandBlock(command) {
  const block = el("div", { class: "command-block", "data-copy": command }, [
    el("code", { text: command }),
    el("button", { type: "button", class: "copy", "aria-label": "Copy command", text: "Copy" }),
  ]);
  return block;
}

function typeMeta(type) {
  return state.data.types.find((t) => t.type === type);
}

/* Counts ------------------------------------------------------------------------- */

function renderCounts() {
  const { types, plugins } = state.data;
  els.counts.replaceChildren(
    ...types.map((t) =>
      el("li", {}, [
        el(
          "a",
          { href: buildHash({ view: "items", item: null, type: t.type }), "data-type": t.type },
          [el("strong", { text: String(t.count) }), el("span", { text: t.label.toLowerCase() })],
        ),
      ]),
    ),
    el("li", {}, [
      el("a", { href: "#/plugins", "data-type": "plugin" }, [
        el("strong", { text: String(plugins.length) }),
        el("span", { text: "plugins" }),
      ]),
    ]),
  );
}

/* Filters ---------------------------------------------------------------------- */

function chip({ value, label, count, pressed, type }) {
  return el(
    "button",
    {
      type: "button",
      class: "chip",
      "data-value": value,
      "aria-pressed": pressed ? "true" : "false",
      disabled: count === 0 && !pressed,
    },
    [
      type ? dot(type) : null,
      el("span", { class: "label", text: label }),
      el("span", { class: "n", text: String(count) }),
    ],
  );
}

function countBy(items, key) {
  const map = new Map();
  for (const item of items) {
    const values = key === "plugins" ? item.plugins : [item[key]];
    for (const v of values) map.set(v, (map.get(v) ?? 0) + 1);
  }
  return map;
}

function renderFilters() {
  const { items, types, plugins } = state.data;

  // Each group's counts ignore its own selection, so the numbers answer
  // "what would I get if I picked this instead" rather than collapsing to zero.
  const byType = countBy(applyFilters(items, { ignore: "type" }), "type");
  const byCategory = countBy(applyFilters(items, { ignore: "category" }), "category");
  const byPlugin = countBy(applyFilters(items, { ignore: "plugin" }), "plugins");

  els.filterType.replaceChildren(
    ...types.map((t) =>
      chip({
        value: t.type,
        label: t.label,
        count: byType.get(t.type) ?? 0,
        pressed: state.type === t.type,
        type: t.type,
      }),
    ),
  );

  const categories = [...new Set(items.map((i) => i.category))].sort();
  els.filterCategory.replaceChildren(
    ...categories.map((c) =>
      chip({
        value: c,
        label: titleCase(c),
        count: byCategory.get(c) ?? 0,
        pressed: state.category === c,
      }),
    ),
  );

  els.filterPlugin.replaceChildren(
    ...plugins.map((p) =>
      chip({
        value: p.name,
        label: p.name,
        count: byPlugin.get(p.name) ?? 0,
        pressed: state.plugin === p.name,
      }),
    ),
  );

  els.clear.hidden = !(state.q || state.type || state.category || state.plugin);
  if (els.search.value !== state.q) els.search.value = state.q;
}

function titleCase(slug) {
  return slug
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

/* Rows --------------------------------------------------------------------------- */

function renderRows() {
  const visible = applyFilters(state.data.items);
  const terms = normalize(state.q).split(/\s+/).filter(Boolean);
  const total = state.data.items.length;

  els.summary.textContent =
    visible.length === total ? `${total} items` : `${visible.length} of ${total} items`;
  els.empty.hidden = visible.length > 0;
  els.rows.hidden = visible.length === 0;

  const frag = document.createDocumentFragment();
  for (const item of visible) {
    frag.append(
      el("li", { class: "row" }, [
        el(
          "a",
          { class: "row-link", href: buildHash({ item: item.key }), "data-type": item.type },
          [
            el("span", { class: "row-rail", "aria-hidden": "true" }),
            el("span", { class: "row-main" }, [
              el("span", { class: "row-head" }, [
                el("code", { class: "row-name" }, highlight(item.name, terms)),
                el("span", { class: "row-type", text: item.type }),
                el("span", { class: "row-category", text: item.category }),
              ]),
              el("span", { class: "row-desc" }, highlight(item.description, terms)),
            ]),
          ],
        ),
      ]),
    );
  }
  els.rows.replaceChildren(frag);
}

/* Plugins view ------------------------------------------------------------------ */

function renderPlugins() {
  const { plugins, items } = state.data;
  const byKey = new Map(items.map((i) => [i.key, i]));
  els.pluginList.replaceChildren(
    ...plugins.map((p) => {
      const members = p.items.map((key) => byKey.get(key)).filter(Boolean);
      const counts = state.data.types
        .map((t) => [members.filter((m) => m.type === t.type).length, t.noun.toLowerCase()])
        .filter(([n]) => n > 0)
        .map(([n, noun]) => `${n} ${noun}${n === 1 ? "" : "s"}`)
        .join(", ");
      return el("li", { class: "plugin", id: `plugin-${p.name}` }, [
        el("div", { class: "plugin-head" }, [
          el("code", { class: "plugin-name", text: p.name }),
          el("span", { class: "plugin-summary", text: counts }),
        ]),
        el("p", { class: "plugin-desc", text: p.description }),
        commandBlock(`/plugin install ${p.name}@${state.data.registry.name}`),
        el(
          "ul",
          { class: "plugin-items" },
          members.map((m) =>
            el("li", {}, [
              el("a", { href: buildHash({ view: "items", item: m.key }), title: m.title }, [
                dot(m.type),
                m.name,
              ]),
            ]),
          ),
        ),
      ]);
    }),
  );
}

/* Detail panel -------------------------------------------------------------------- */

function renderDetail() {
  const item = state.item ? state.data.items.find((i) => i.key === state.item) : null;
  if (!item) {
    els.detail.hidden = true;
    els.backdrop.hidden = true;
    return;
  }

  const { registry } = state.data;
  const meta = typeMeta(item.type);
  const shadcn = `npx shadcn@latest add ${registry.owner}/${item.name}`;

  const pluginSection =
    item.plugins.length > 0
      ? [
          el("h3", { text: "Install as a plugin" }),
          el("p", {
            text:
              item.plugins.length === 1
                ? `Bundled in the ${item.plugins[0]} plugin. Add the marketplace once, then:`
                : `Bundled in ${item.plugins.length} plugins. Add the marketplace once, then any of:`,
          }),
          ...item.plugins.map((name) => commandBlock(`/plugin install ${name}@${registry.name}`)),
        ]
      : [
          el("h3", { text: "Install as a plugin" }),
          el("p", {
            class: "detail-note",
            text: "Not part of any plugin; install it with the shadcn CLI.",
          }),
        ];

  const hookNote =
    item.type === "hook"
      ? el("p", {
          class: "detail-note",
          text: "Installed this way, a hook still needs its documented block added to .claude/settings.json.",
        })
      : null;

  const children = [
    el("div", { class: "detail-top", "data-type": item.type }, [
      el("div", {}, [
        el("p", { class: "detail-kind" }, [
          meta.noun,
          " ",
          el("span", { class: "row-category", text: `in ${item.category}` }),
        ]),
        el("h2", { text: item.name }),
        item.title.toLowerCase() !== titleCase(item.name).toLowerCase()
          ? el("p", { class: "detail-title", text: item.title })
          : null,
      ]),
      el("button", { type: "button", class: "close", "aria-label": "Close", text: "×" }),
    ]),
    el("p", { class: "detail-desc", text: item.description }),
    ...pluginSection,
    el("h3", { text: "Install as a single item" }),
    el("p", { text: "Run from your project root; it lands under .claude/." }),
    commandBlock(shadcn),
    hookNote,
    el("h3", { text: "Files installed" }),
    el(
      "ul",
      { class: "targets" },
      item.targets.map((t) => el("li", { text: t })),
    ),
    el("div", { class: "detail-links" }, [
      el("a", { href: item.docs, rel: "noopener", text: "View source on GitHub" }),
      el("a", {
        href: buildHash({
          view: "items",
          item: null,
          type: item.type,
          category: "",
          plugin: "",
          q: "",
        }),
        text: `All ${meta.label.toLowerCase()}`,
      }),
    ]),
  ];
  els.detailInner.replaceChildren(...children.filter(Boolean));

  els.detail.hidden = false;
  els.backdrop.hidden = false;
  els.detailInner.querySelector(".close").focus({ preventScroll: true });
}

/* Views --------------------------------------------------------------------------- */

function renderNav() {
  for (const a of document.querySelectorAll("[data-nav]")) {
    if (a.dataset.nav === state.view) a.setAttribute("aria-current", "page");
    else a.removeAttribute("aria-current");
  }
}

function render() {
  if (!state.data) return;
  els.viewItems.hidden = state.view !== "items";
  els.viewPlugins.hidden = state.view !== "plugins";
  els.viewInstall.hidden = state.view !== "install";
  renderNav();
  if (state.view === "items") {
    renderFilters();
    renderRows();
  }
  renderDetail();
  document.body.style.overflow = state.item ? "hidden" : "";
}

/* Events ---------------------------------------------------------------------------- */

function closeDetail() {
  navigate({ item: null });
}

function onChipClick(group, event) {
  const button = event.target.closest(".chip");
  if (!button) return;
  const value = button.dataset.value;
  navigate({ [group]: state[group] === value ? "" : value, item: null });
}

async function copy(text, button) {
  try {
    await navigator.clipboard.writeText(text);
    button.dataset.done = "";
    button.textContent = "Copied";
    setTimeout(() => {
      delete button.dataset.done;
      button.textContent = "Copy";
    }, 1500);
  } catch {
    // Clipboard is unavailable (insecure context, denied permission); the
    // command is still selectable text next to the button.
    button.textContent = "Select";
    const code = button.parentElement.querySelector("code");
    const range = document.createRange();
    range.selectNodeContents(code);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
  }
}

function bindEvents() {
  window.addEventListener("hashchange", () => {
    readHash();
    render();
  });

  let debounce = 0;
  els.search.addEventListener("input", () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => {
      // Replace rather than push so typing does not fill the history.
      const hash = buildHash({ q: els.search.value.trim(), item: null });
      if (hash !== location.hash) history.replaceState(null, "", hash);
      readHash();
      render();
      els.search.focus();
    }, 120);
  });

  els.filterType.addEventListener("click", (e) => onChipClick("type", e));
  els.filterCategory.addEventListener("click", (e) => onChipClick("category", e));
  els.filterPlugin.addEventListener("click", (e) => onChipClick("plugin", e));
  els.clear.addEventListener("click", () =>
    navigate({ q: "", type: "", category: "", plugin: "", item: null }),
  );

  els.backdrop.addEventListener("click", closeDetail);
  document.addEventListener("click", (e) => {
    if (e.target.closest(".close")) closeDetail();
    const copyButton = e.target.closest(".copy");
    if (copyButton) copy(copyButton.parentElement.dataset.copy, copyButton);
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && state.item) {
      closeDetail();
      return;
    }
    const typing = ["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName);
    if (e.key === "/" && !typing) {
      e.preventDefault();
      navigate({ view: "items", item: null });
      els.search.focus();
      els.search.select();
    }
  });
}

/* Boot -------------------------------------------------------------------------------- */

async function boot() {
  bindEvents();
  readHash();
  try {
    const res = await fetch(DATA_URL);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    state.data = await res.json();
  } catch {
    els.loadError.hidden = false;
    els.viewItems.hidden = true;
    return;
  }
  renderCounts();
  renderPlugins();
  render();
}

boot();
